package com.careerconnect.backend.controller; import com.careerconnect.backend.dto.*; import com.careerconnect.backend.service.AuthService; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") @CrossOrigin public class AuthController{private final AuthService service; public AuthController(AuthService service){this.service=service;} @PostMapping("/register") public AuthResponse register(@RequestBody RegisterRequest r){return service.register(r);} @PostMapping("/login") public AuthResponse login(@RequestBody LoginRequest r){return service.login(r);}}
